target = {1:[0,1,0,1,0,1],2:[1,1,0,1,0,1],3:[0,0,0,1,0,1],4:[1,1,1,1,0,1],5:[0,0,0,0,0,1]}
import math
matches=[]
for a in range(-3,5):
 for b in range(-3,4):
  ok=0; tot=0
  for y,row in target.items():
   for x,t in enumerate(row,1):
    n=x+y+a;k=x+b
    if n>=0 and 0<=k<=n:
     v=math.comb(n,k)%2
     ok+=v==t; tot+=1
  matches.append((ok/tot,ok,tot,a,b))
sorted(matches,reverse=True)[:20]

